// The most recent occurrence of `frequency` at or before `now`, as a Date —
// `null` for `manual`, which has none. `now` may be a Date or anything the Date
// constructor accepts; `schedule` is normalized here, so callers need not.
export function anchorInstant(frequency, schedule, now) {
  const s = normalizeSchedule(schedule);
  const at = new Date(now);
  const nowMs = at.getTime();
  // Total over the accepted vocabulary, not just the canonical one: the door normalizes every
  // LOADED declaration, and normalizing here too means a direct caller — a test, `slots.mjs`, a
  // frequency read off something other than a discovered task — cannot get a different answer.
  const freq = normalizeFrequency(frequency);

  if (freq === 'manual') return null;

  if (freq === 'daily') {
    // Walk anchor DATES back from today until the instant is ≤ now: today's anchor hour may not
    // have come yet, in which case the most recent occurrence is yesterday's.
    let anchor = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
    for (;;) {
      const time = new Date(anchor.getTime() + s.dailyHour * HOUR_MS);
      if (time.getTime() <= nowMs) return time;
      anchor = new Date(anchor.getTime() - DAY_MS);
    }
  }

  if (freq === 'weekly') {
    const targetDow = WEEKDAYS.indexOf(s.weeklyDay);
    let date = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
    // Up to 8 steps guarantees the previous week's occurrence even when today is
    // the weekly day but earlier than dailyHour.
    for (let i = 0; i < 8; i += 1) {
      if (date.getUTCDay() === targetDow) {
        const time = new Date(date.getTime() + s.dailyHour * HOUR_MS);
        if (time.getTime() <= nowMs) return time;
      }
      date = new Date(date.getTime() - DAY_MS);
    }
    // Unreachable in practice (a matching weekday always exists within 7 days).
    throw new Error(`no weekly occurrence resolved for ${s.weeklyDay}`);
  }

  if (freq === 'monthly') {
    let year = at.getUTCFullYear();
    let month = at.getUTCMonth();
    for (;;) {
      const day = Math.min(s.monthlyDay, daysInMonth(year, month)); // clamp to month length (docs/PRINCIPLES.md)
      const time = new Date(Date.UTC(year, month, day) + s.dailyHour * HOUR_MS);
      if (time.getTime() <= nowMs) return time;
      month -= 1;
      if (month < 0) { month = 11; year -= 1; }
    }
  }

  throw new Error(`unknown frequency "${frequency}"`);
}

// --- the cadence terms ----------------------------------------------------------
// How a task states WHEN it runs, inside its own `preconditions`
// (docs/PRINCIPLES.md): the engine keeps no calendar of its own, so the cadence is one of the
// task's conditions, read off its own run history at every scheduler tick.
//
//   due:<daily|weekly|monthly>   no run since that cadence's most recent anchor on
//                                this repo's schedule — fixed hours, no drift
//   last-run-over:<12h|1d|7d>    the newest run started more than that long ago
//
// Whether a task is asked at all is its `trigger`, not the shape of this list: a
// task nothing asks may still state conditions, which are judged when somebody
// creates an item for it (the retired `frequency: manual` is `trigger: 'request'`).
//
// The parse lives here, beside the frequency vocabulary it replaces, and imports
// nothing: the dashboard's browser bundle reads a cadence the way the scheduler does.
export const CADENCES = ['daily', 'weekly', 'monthly'];
export const DUE_TERM = 'due';
export const ELAPSED_TERM = 'last-run-over';
export const NOT_FAILED_TERM = 'last-run-not-failed';
export const NOT_PARKED_TERM = 'last-run-not-parked';

// `12h`, `1d`, `7d` — a whole number of hours or days, nothing else.
const DURATION_RE = /^(\d+)(h|d)$/;
export function parseDuration(text) {
  const m = DURATION_RE.exec(String(text ?? ''));
  if (!m) return null;
  const n = Number(m[1]);
  return n > 0 ? n * (m[2] === 'h' ? HOUR_MS : DAY_MS) : null;
}

// The term references an expression carries: each entry split on `||`, each
// reference `{ name, arg }` with the argument after the first colon. The same
// grammar precondition-policy.mjs parses, re-spelled here so this module stays
// import-free; the policy engine's parse is the one that validates.
const alternativesOf = (entry) => String(entry ?? '').split('||').map((t) => t.trim()).filter(Boolean)
  .map((t) => { const c = t.indexOf(':'); return c === -1 ? { name: t, arg: null } : { name: t.slice(0, c).trim(), arg: t.slice(c + 1).trim() }; });
const entriesOf = (preconditions) => (Array.isArray(preconditions) ? preconditions : []).map(alternativesOf);

// The cadence a declaration states — `{ kind: 'due', cadence }`, `{ kind:
// 'elapsed', ms, text }`, or null for a task with no cadence term (asked at every
// tick while it states any condition, it runs whenever those hold). The first
// cadence term wins.
export function cadenceOf(preconditions) {
  for (const ref of entriesOf(preconditions).flat()) {
    if (ref.name === DUE_TERM && CADENCES.includes(ref.arg)) return { kind: 'due', cadence: ref.arg };
    if (ref.name === ELAPSED_TERM) {
      const ms = parseDuration(ref.arg);
      if (ms) return { kind: 'elapsed', ms, text: ref.arg };
    }
  }
  return null;
}

// Whether the declaration states any condition at all. Not a scheduling answer on
// its own — `trigger` is that — but what the contract's door reads to derive one
// for a declaration written before the field existed (#1789). An entry carrying
// only separators states nothing, which is why this is not a length test.
export const statesConditions = (preconditions) => entriesOf(preconditions).some((alts) => alts.length > 0);

// A term gates when it is a whole conjunct of the expression — `['x', …]` gates,
// `['due:daily || x']` merely widens.
const gatesOn = (preconditions, term) =>
  entriesOf(preconditions).some((alts) => alts.length === 1 && alts[0].name === term && alts[0].arg === null);

// A task stops past its own failure park only when it says so: nothing holds a
// task's lane but its own word — `last-run-not-failed` for that park alone, or
// `last-run-not-parked`, which holds behind all four and so answers this too.
export const holdsOnFailure = (preconditions) =>
  gatesOn(preconditions, NOT_FAILED_TERM) || gatesOn(preconditions, NOT_PARKED_TERM);

// Whether the declaration holds its lane behind EVERY park, the three a person's
// inbox owns included. A reader showing what happens next needs the wider answer
// as well: a task held behind an approval park is not being asked on schedule,
// and an anchor shown there promises a run the task declines.
export const holdsOnAnyPark = (preconditions) => gatesOn(preconditions, NOT_PARKED_TERM);

// What the retired `frequency` field always meant, as the term that now says it —
// or null for `manual`, which meant no schedule at all and so adds no term.
export const cadenceTermFor = (frequency) =>
  (normalizeFrequency(frequency) === 'manual' ? null : `${DUE_TERM}:${normalizeFrequency(frequency)}`);
// Anchors — when a cadence's occurrence falls (docs/PRINCIPLES.md).
//
// The arithmetic lives in `calendar.mjs`; this module exposes exactly the two
// questions asked of it — "which occurrence is current" (what a `due:` term
// measures a task's run history against) and "when is the next one" (what the
// dashboard renders) — plus the period a cadence repeats on, and the period a
// TASK keeps, read off its own cadence term.
//
// Pure and stateless: `now` is always injected, every value is UTC.

import { anchorInstant, normalizeFrequency, cadenceOf } from '../contract/calendar.mjs';

const HOUR_MS = 3600e3;
const DAY_MS = 24 * HOUR_MS;

// One period of a cadence word (`daily`, `weekly`, `monthly` — and the retired
// `frequency` field's values, `manual` having none), in ms — the unit the
// janitor's stale-ready rule counts in (PRINCIPLES.md) and the coarse step
// `nextAnchor` walks.
export function periodMs(frequency) {
  // Normalized like `anchorInstant`. Today this changes no answer — every retired token maps to
  // `daily`, which is also the fallthrough below — so it is insurance, not the thing carrying the
  // behaviour: it is what keeps this correct if `LEGACY_FREQUENCIES` ever gains a mapping that is
  // not `daily`. What DOES carry it is the door plus that fallthrough, and why it matters is
  // sharp: this feeds the janitor's stale-ready bound and the precondition's signal window, so a
  // token resolving to an HOUR here parks a member's task needs-human on every sweep (PRINCIPLES.md).
  const freq = normalizeFrequency(frequency);
  if (freq === 'weekly') return 7 * DAY_MS;
  if (freq === 'monthly') return 31 * DAY_MS;
  if (freq === 'manual') return null;
  return DAY_MS;
}

// The period a TASK keeps, read off the cadence term its declaration states: a
// `due:` cadence's period, a `last-run-over:` duration, and null for a task with
// no cadence term (asked at every tick, it runs on movement or when woken).
export function taskPeriodMs(decl) {
  const cadence = cadenceOf(decl?.preconditions);
  if (cadence?.kind === 'due') return periodMs(cadence.cadence);
  if (cadence?.kind === 'elapsed') return cadence.ms;
  return null;
}

// The most recent occurrence at or before `now`, as a Date. `manual` has none —
// nothing schedules it — so null is the whole answer.
export const mostRecentAnchor = anchorInstant;

// The earliest occurrence strictly after `now` — what a rolled item is stamped
// with. Derived by walking `mostRecentAnchor` forward rather than by adding a
// period: monthly anchors are not a fixed distance apart, and a `daily-2h` whose
// instant wraps to the previous calendar day is exactly the case a fixed add gets
// wrong. The coarse step is under one period, so the loop advances by at most two
// steps and never overshoots an occurrence.
export function nextAnchor(frequency, schedule, now) {
  if (normalizeFrequency(frequency) === 'manual') return null;
  const from = mostRecentAnchor(frequency, schedule, now).getTime();
  const step = normalizeFrequency(frequency) === 'monthly' ? 28 * DAY_MS : periodMs(frequency);
  for (let t = from + step; ; t += step) {
    const candidate = mostRecentAnchor(frequency, schedule, new Date(t));
    if (candidate.getTime() > from) return candidate;
  }
}
// Is a default-branch commit GENUINE PROJECT WORK, or the machinery moving? The one
// test, published because two very different readers ask it: the signal collectors,
// which gate a precondition on whether the repo moved in a window, and a cross-repo
// reader (the dashboard) deciding whether a member looks quiet. A second notion of
// "meaningful" would mark a member sleepy on the very commits its own scheduler counts
// as movement.
//
// Import-light and free of `node:` on purpose, like dormancy.mjs: the dashboard reads
// this in the browser through the pack's published public/.

import { taskFromMessage } from '../contract/task-trailer.mjs';

// Bot/CI housekeeping and Claudinite's own automated writes, by MESSAGE. The queue's
// own vocabulary (`[claudinite-task]`, `[claudinite-work]`) is excluded here so
// neither dispatch mechanism ever self-triggers: a queue-mode repo's work items are
// repo activity to every precondition watching issues.
export const HOUSEKEEPING = /\[skip ci\]|(^|\n)\s*baselin(e|ing)\b|claudinite[ -](baselin|maintenance|growth|task|work)|seed default-on/i;

// The exclusion the message cannot express: a commit that touched nothing outside
// `.claudinite/` moved the repo's own working rules, not the project. Every consumer
// means "genuine project work" by this — something shippable changed (store-release),
// there is a lesson to extract (growth-extract), a comment may have drifted
// (improve-comments) — and none of those is true of a corpus edit. Message and author
// cannot catch it: a human landing a lesson PR writes an ordinary message under their
// own login, so the growth lifecycle's own landed output re-armed it the next night
// and a repo could never go quiet (TLDR #319).
//
// An empty list is UNKNOWN, never "touched only .claudinite/" — a bare `every` is
// vacuously true on it and would silently retire the trigger for every commit whose
// detail read failed. Require at least one known path before the exclusion applies.
const CORPUS_ONLY = (files) => files.length > 0 && files.every((f) => f.startsWith('.claudinite/'));

// The test. `files` is the commit's changed paths where the caller resolved them, and
// `null` where it did not: a reader working from a commit LISTING has no file list and
// cannot afford a read per commit, so it gets the author, trailer and message
// exclusions and states that the corpus-only one did not run. The trailer is the
// AUTHORITY for anything written after it existed — a commit a scheduled task wrote
// says so itself — and the message and author exclusions stay because history
// predating the trailer still needs classifying and because they also cover
// non-task housekeeping.
export function isSubstantiveCommit(commit, files = null) {
  const login = commit?.author?.login ?? commit?.author ?? '';
  if (typeof login === 'string' && login.endsWith('[bot]')) return false;
  const message = commit?.commit?.message ?? commit?.message ?? '';
  if (taskFromMessage(message)) return false;
  if (files !== null && CORPUS_ONLY(files)) return false;
  return !HOUSEKEEPING.test(message);
}
// The task declaration as a file and as text — the half every reader can load,
// the dashboard's browser bundle included: no Node built-ins here. The fs half
// (finding and loading a folder's declaration) is task-declaration.mjs, which
// re-exports this.
//
// `task.json` is the declaration: plain data, pointing at `task.schema.json`
// through `$schema`, and readable by anything that can parse JSON. It is the
// only declaration file a task folder may carry.

export const TASK_DECLARATION_FILE = 'task.json';

// The file-listing form of the same fact, for the checks and the dashboard, which
// select a task folder out of a path list rather than probing a directory. Group 1
// is the task's directory name.
export const TASK_DECLARATION_PATH_RE = /(^|\/)tasks\/([^/]+)\/task\.json$/;
export const isTaskDeclarationPath = (path) => TASK_DECLARATION_PATH_RE.test(path);

// A `task.json`'s text as the declaration object. `$schema` is the editor's
// pointer, not a field of the contract, and leaves here.
export function parseTaskDeclaration(text) {
  const decl = JSON.parse(text);
  if (decl !== null && typeof decl === 'object' && !Array.isArray(decl)) delete decl.$schema;
  return decl;
}

// The order a declaration's keys are written in, grouped by what they say: what
// the task is, when it runs, what it may write, then the two phases — code work,
// then the agent. A key not listed keeps its place after the listed ones.
export const KEY_ORDER = [
  '$schema', 'id', 'description',
  'schedule_after', 'trigger', 'preconditions',
  'expected_outcome', 'automerge', 'on_interrupt', 'invocation_endpoint',
  'code_work', 'code_work_timeout', 'code_work_required_secrets',
  'agent_model', 'model_from_request', 'agent_instructions', 'agent_execution_timeout',
