const rel = (from, to) => { let r = relative(dirname(from), to); if (!r.startsWith('.')) r = './' + r; return r; };
const report = [];
for (const file of files) {
  let text = readFileSync(join(ROOT, file), 'utf8');
  const before = text;
  // static imports, possibly multi-line: import { a, b } from '…/x.mjs';
  text = text.replace(/import\s*\{([^}]*)\}\s*from\s*'([^']+\/(?:work-item|leases|task-trailer)\.mjs)';/g, (whole, names, spec) => {
    const target = join(dirname(file), spec);
    if (!RETIRED.includes(target)) return whole;
    const list = names.split(',').map((s) => s.trim()).filter(Boolean);
    const c = list.filter((n) => n.split(/\s+as\s+/)[0] in constants);
    const g = list.filter((n) => !(n.split(/\s+as\s+/)[0] in constants) && n.split(/\s+as\s+/)[0] in grammar);
    const missing = list.filter((n) => !c.includes(n) && !g.includes(n));
    if (missing.length) report.push(`${file}: unresolved ${missing.join(', ')}`);
    const out = [];
    const fmt = (arr, mod) => {
      const one = `import { ${arr.join(', ')} } from '${rel(file, `${PUB}/${mod}`)}';`;
      if (one.length <= 100) return one;
      const lines = []; let cur = ' ';
      for (const n of arr) { if ((cur + ' ' + n + ',').length > 98) { lines.push(cur); cur = ' '; } cur += ' ' + n + ','; }
      lines.push(cur);
      return `import {\n${lines.join('\n')}\n} from '${rel(file, `${PUB}/${mod}`)}';`;
    };
    if (c.length) out.push(fmt(c, 'task-constants.mjs'));
    if (g.length) out.push(fmt(g, 'work-item-grammar.mjs'));
    return out.join('\n');
  });
  // dynamic imports of leases (all names are constants)
  text = text.replace(/import\('([^']+\/leases\.mjs)'\)/g, (whole, spec) => {
    const target = join(dirname(file), spec);
    return RETIRED.includes(target) ? `import('${rel(file, `${PUB}/task-constants.mjs`)}')` : whole;
  });
  if (text !== before) { writeFileSync(join(ROOT, file), text); report.push(`rewrote ${file}`); }
  if (/(work-item|leases|task-trailer)\.mjs'/.test(text)) {
    const left = [...text.matchAll(/.*(work-item|leases|task-trailer)\.mjs'.*/g)].map((m) => m[0].trim());
    for (const l of left) if (RETIRED.includes(join(dirname(file), /'([^']+)'/.exec(l)?.[1] ?? ''))) report.push(`${file}: LEFT ${l}`);
