import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const MAP = {
  READY: 'STATUS_READY', BLOCKED: 'STATUS_BLOCKED', EXECUTING: 'STATUS_RUNNING_EXECUTOR',
  AGENT: 'STATUS_RUNNING_AGENT', TASK_DONE: 'STATUS_DONE', TASK_OBSOLETE: 'STATUS_REJECTED',
  NEEDS_HUMAN_ACTION: 'STATUS_NEEDS_HUMAN_ACTION', NEEDS_HUMAN_DECISION: 'STATUS_NEEDS_HUMAN_DECISION',
  NEEDS_HUMAN_APPROVAL: 'STATUS_NEEDS_HUMAN_APPROVAL', NEEDS_HUMAN_FAILURE: 'STATUS_NEEDS_HUMAN_FAILURE',
  TRIAGE_LABELS: 'PARK_STATUSES', STATE_LABELS: 'LIVE_STATUSES', STATE_STATUSES: 'LIVE_STATUSES',
  NEEDS_HUMAN_LABEL: 'NEEDS_HUMAN',
};
const SKIP = new Set(['packs/claudinite-tasks/public/task-constants.mjs', 'packs/claudinite-tasks/public/work-items.mjs']);
const names = Object.keys(MAP).join('|');
const inSpecifiers = new RegExp(`((?:import|export)\\s*\\{)([^}]*)(\\}\\s*from\\s*'[^']+')`, 'g');
const files = execFileSync('git', ['ls-files', '*.mjs']).toString().trim().split('\n').filter((f) => !SKIP.has(f));
const touched = [];
for (const f of files) {
  const src = readFileSync(f, 'utf8');
  // only files that import or re-export an alias by name from some module
  let imports = false;
  for (const m of src.matchAll(inSpecifiers)) if (new RegExp(`\\b(${names})\\b`).test(m[2])) imports = true;
  if (!imports) continue;
  let out = src.replace(new RegExp(`\\b(${names})\\b`, 'g'), (_, n) => MAP[n]);
  // dedupe specifiers inside each import/export block
  out = out.replace(inSpecifiers, (_, open, list, close) => {
    const seen = new Set();
    const parts = list.split(',').map((s) => s.trim()).filter(Boolean);
    const kept = parts.filter((p) => { const key = p.replace(/^.* as /, ''); if (seen.has(key)) return false; seen.add(key); return true; });
    const multiline = list.includes('\n');
    return open + (multiline ? '\n  ' + kept.join(', ') + ',\n' : ' ' + kept.join(', ') + ' ') + close;
  });
  if (out !== src) { writeFileSync(f, out); touched.push(f); }
}
console.log(touched.join('\n'));
EOF
